321:   bindTouch() {
322:     const joy = this.ui.el.joyZone;
323:     const knob = this.ui.el.joyKnob;
324:     const look = document.getElementById('look-zone');
325:     let joyId = null;
326:     let lookId = null;
327:     let lookX = 0;
328:     let lookY = 0;
329:     const maxR = 38;
330:     const setJoy = (event) => {
331:       const rect = joy.getBoundingClientRect();
332:       const cx = rect.left + rect.width / 2;
333:       const cy = rect.top + rect.height / 2;
334:       let dx = event.clientX - cx;
335:       let dy = event.clientY - cy;
336:       const d = Math.hypot(dx, dy);
337:       if (d > maxR) {
338:         dx = (dx / d) * maxR;
339:         dy = (dy / d) * maxR;
340:       }
341:       knob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
342:       this.touchMove.x = dx / maxR;
343:       this.touchMove.y = dy / maxR;
344:       this.touchMove.active = true;
345:     };
346:     const resetJoy = () => {
347:       joyId = null;
348:       this.touchMove.x = 0;
349:       this.touchMove.y = 0;
350:       this.touchMove.active = false;
351:       knob.style.transform = 'translate(-50%, -50%)';
352:     };
353:     joy.addEventListener('pointerdown', (event) => {
354:       joyId = event.pointerId;
355:       joy.setPointerCapture(event.pointerId);
356:       setJoy(event);
357:     });
358:     joy.addEventListener('pointermove', (event) => {
359:       if (joyId === event.pointerId) setJoy(event);
360:     });
361:     joy.addEventListener('pointerup', resetJoy);
362:     joy.addEventListener('pointercancel', resetJoy);
363:     look.addEventListener('pointerdown', (event) => {
364:       lookId = event.pointerId;
365:       lookX = event.clientX;
366:       lookY = event.clientY;
367:       look.setPointerCapture(event.pointerId);
368:     });
369:     look.addEventListener('pointermove', (event) => {
370:       if (lookId !== event.pointerId) return;
371:       const dx = event.clientX - lookX;
372:       const dy = event.clientY - lookY;
373:       lookX = event.clientX;
374:       lookY = event.clientY;
375:       this.camYaw -= dx * 0.006;
376:       this.orbitPitch = clamp(this.orbitPitch + dy * 0.004, 0.02, 1.05);
377:     });
378:     look.addEventListener('pointerup', () => { lookId = null; });
379:     look.addEventListener('pointercancel', () => { lookId = null; });
380:     const sprintBtn = this.ui.el.btnSprint;
381:     sprintBtn.addEventListener('pointerdown', (event) => {
382:       event.preventDefault();
383:       this.touchSprint = true;
384:       sprintBtn.classList.add('on');
385:     });
386:     const stopSprint = () => {
387:       this.touchSprint = false;
388:       sprintBtn.classList.remove('on');
389:     };
390:     sprintBtn.addEventListener('pointerup', stopSprint);
391:     sprintBtn.addEventListener('pointercancel', stopSprint);
392:     this.ui.el.btnCrouch.addEventListener('click', () => this.toggleCrouch());
393:     this.ui.el.btnCamera.addEventListener('click', () => this.toggleCamera());
394:     this.ui.el.btnInteract.addEventListener('click', () => this.tryInteract());
395:     this.ui.el.btnLight.addEventListener('click', () => this.toggleFlashlight());
396:     this.ui.el.btnMap.addEventListener('click', () => {
397:       if (this.state === 'playing') this.openMap();
398:       else if (this.state === 'map') this.closeMap();
399:     });
400:     this.ui.el.btnPause.addEventListener('click', () => this.pause());
401:   }
