1001:   getZoneName() {
1002:     if (this.player.inside) return 'LABORATORY LOBBY // SECURE';
1003:     const p = this.player.position;
1004:     for (const core of this.jungle.cores) {
1005:       if (!core.collected && p.distanceTo(core.position) < 30) {
1006:         return `${core.landmark} // CLEARING`;
1007:       }
1008:     }
