476:   buildMapTerrain(w, h) {
477:     const canvas = document.createElement('canvas');
478:     canvas.width = w;
479:     canvas.height = h;
480:     const ctx = canvas.getContext('2d');
481:     const cell = 8;
482:     for (let y = 0; y < h; y += cell) {
483:       for (let x = 0; x < w; x += cell) {
484:         const wx = ((x + cell / 2) / w - 0.5) * 500;
485:         const wz = ((y + cell / 2) / h - 0.5) * 500;
486:         const ht = terrainHeight(wx, wz);
487:         const v = clamp(0.16 + ht / 42, 0.04, 0.46);
488:         const moss = clamp(0.3 + ht / 55, 0.12, 0.56);
489:         ctx.fillStyle = `rgb(${Math.floor(12 + v * 40)}, ${Math.floor(25 + moss * 54)}, ${Math.floor(18 + v * 30)})`;
490:         ctx.fillRect(x, y, cell, cell);
491:         if (ht > 7 && (x + y) % 32 === 0) {
492:           ctx.fillStyle = 'rgba(137,159,104,0.1)';
493:           ctx.fillRect(x, y, cell, cell);
494:         }
495:       }
496:     }
497:     // Contour speckle.
498:     ctx.globalAlpha = 0.15;
499:     for (let i = 0; i < 250; i += 1) {
500:       ctx.fillStyle = i % 3 ? '#779057' : '#233f25';
501:       ctx.fillRect(Math.floor(Math.random() * w), Math.floor(Math.random() * h), 2, 2);
502:     }
503:     ctx.globalAlpha = 1;
