247:   setState(next, reason = '') {
248:     if (this.state === next) return;
249:     const previous = this.state;
250:     this.state = next;
251:     this.stateTimer = 0;
252:     if (next === 'chase') {
253:       this.chaseDuration = 0;
254:       if (this.roarCooldown <= 0) {
255:         this.roarCooldown = 7;
256:         this.callbacks.onRoar?.(this.position, previous);
257:       }
258:     }
259:     if (next === 'alert') {
260:       this.callbacks.onAlert?.({ position: this.position.clone(), previous, reason });
261:     }
262:     this.callbacks.onStateChange?.(next, previous, reason);
263:   }
