265:   choosePatrolTarget() {
266:     const angle = Math.random() * Math.PI * 2;
267:     const radius = 70 + Math.random() * 120;
268:     let x = Math.cos(angle) * radius;
269:     let z = Math.sin(angle) * radius;
270:     if (Math.hypot(x, z) < 35) {
271:       x *= 2.1;
272:       z *= 2.1;
273:     }
274:     this.patrolTarget.set(clamp(x, -220, 220), 0, clamp(z, -220, 220));
275:     this.stateTimer = 0;
276:   }
