278:   hearNoise(event) {
279:     if (this.dead) return;
280:     const distance = this.position.distanceTo(event.position);
281:     const radius = event.radius * this.aggression;
282:     if (distance > radius) return;
283:     const loudness = clamp(event.loudness * (1 - distance / radius), 0, 1);
284:     this.lastHeard.copy(event.position);
285:     this.lastHeardAge = 0;
286:     this.suspicion = clamp(this.suspicion + loudness * 1.45 + 0.12, 0, 1);
287: 
288:     if (this.state === 'patrol' || this.state === 'investigate' || this.state === 'search') {
289:       if ((event.type === 'door' && distance < 90) || (event.type === 'sprint' && loudness > 0.32) || (event.type === 'sprint' && distance < 55)) {
290:         this.setState('chase', event.type);
291:       } else if (this.state !== 'chase') {
292:         this.setState('investigate', event.type);
293:         this.stateTimer = 0;
294:       }
295:     }
296:     if (this.state === 'chase' && loudness > 0.2) {
297:       // Keep a fresh fix on the running target.
298:       this.lastHeard.copy(event.position);
299:       this.lastHeardAge = 0;
300:     }
301:     this.callbacks.onHear?.({ event, distance, loudness });
302:   }
