309:   isBlocked(x, z, lab, jungle) {
310:     const r = this.radius;
311:     if (Math.abs(x) > 244 || Math.abs(z) > 244) return true;
312:     // The laboratory is a true sanctuary: Mossman cannot cross its footprint.
313:     if (lab.isInside(x, z, -1.0)) return true;
314:     for (const c of lab.colliders) {
315:       if (!c.active) continue;
316:       if (x + r > c.minX && x - r < c.maxX && z + r > c.minZ && z - r < c.maxZ) return true;
317:     }
318:     if (!lab.isInside(x, z, 0.3) && jungle.collidesAt(x, z, r)) return true;
319:     return false;
320:   }
