322:   moveTowards(target, dt, targetSpeed, lab, jungle, playerInside) {
323:     _desired.copy(target).sub(this.position);
324:     _desired.y = 0;
325:     const dist = _desired.length();
326:     if (dist < 0.01) return 0;
327:     _desired.normalize();
328:     const desiredYaw = Math.atan2(_desired.x, _desired.z);
329:     const speedRatio = clamp(this.speed / 9.17, 0, 1);
330:     const maxTurn = 1.65 - speedRatio * 0.9;
331:     let delta = angleDelta(this.yaw, desiredYaw);
332:     delta = clamp(delta, -maxTurn * dt, maxTurn * dt);
333:     this.yaw += delta;
334:     // Momentum with deliberate, heavy inertia.
335:     const accel = targetSpeed > this.speed ? 3.2 : 4.2;
336:     this.speed = damp(this.speed, targetSpeed, accel, dt);
337:     _temp.set(Math.sin(this.yaw), 0, Math.cos(this.yaw)).multiplyScalar(this.speed);
338:     this.velocity.x = damp(this.velocity.x, _temp.x + this.avoidBias * this.speed * 0.35, 3, dt);
339:     this.velocity.z = damp(this.velocity.z, _temp.z + this.avoidBias * this.speed * 0.35, 3, dt);
340: 
341:     let nx = this.position.x + this.velocity.x * dt;
342:     let nz = this.position.z + this.velocity.z * dt;
343:     let blocked = false;
344:     if (!this.isBlocked(nx, this.position.z, lab, jungle)) {
345:       this.position.x = nx;
346:     } else {
347:       blocked = true;
348:       this.velocity.x *= -0.08;
349:       this.avoidBias = this.avoidBias || (Math.random() > 0.5 ? 1 : -1);
350:     }
351:     if (!this.isBlocked(this.position.x, nz, lab, jungle)) {
352:       this.position.z = nz;
353:     } else {
354:       blocked = true;
355:       this.velocity.z *= -0.08;
356:       this.avoidBias = this.avoidBias || (Math.random() > 0.5 ? 1 : -1);
357:     }
358:     if (blocked) {
359:       this.blockedTime += dt;
360:       if (this.blockedTime > 0.45) {
361:         this.avoidBias = this.avoidBias > 0 ? -1 : 1;
362:         this.blockedTime = 0;
363:       }
364:       // If pressed against the lab with a player inside, wait and roar.
365:       if (playerInside && lab.isInside(this.position.x, this.position.z, -2.0)) {
366:         this.setState('lurk', 'sanctuary');
367:       }
368:     } else {
369:       this.blockedTime = Math.max(0, this.blockedTime - dt * 0.5);
370:       if (this.state !== 'lurk') this.avoidBias = damp(this.avoidBias, 0, 2.5, dt);
371:     }
372:     this.position.y = groundY(this.position.x, this.position.z);
373:     return dist;
374:   }
375: 
376:   update(dt, player, lab, jungle) {
377:     if (this.dead) return;
378:     this.elapsed += dt;
379:     this.stateTimer += dt;
380:     this.lastHeardAge += dt;
381:     this.attackCooldown = Math.max(0, this.attackCooldown - dt);
382:     this.roarCooldown = Math.max(0, this.roarCooldown - dt);
383:     this.suspicion = Math.max(0, this.suspicion - dt * (this.state === 'chase' ? 0.018 : 0.04));
384:     const playerInside = player.inside;
385:     const distance = this.position.distanceTo(player.position);
386:     const hearingThreshold = playerInside ? 5 : 13;
387: 
388:     // Breathing, footsteps and the player's close-range presence can give
389:     // them away even without a deliberate noise event.
390:     if (!playerInside && distance < hearingThreshold && player.noise > 0.04) {
391:       this.lastHeard.copy(player.position);
392:       this.lastHeardAge = 0;
393:       this.suspicion = Math.min(1, this.suspicion + dt * 0.6);
394:     }
395:     if (!playerInside && distance < 6.5) {
396:       this.lastHeard.copy(player.position);
397:       this.lastHeardAge = 0;
398:       if (this.state !== 'chase' && this.state !== 'attack') this.setState('chase', 'proximity');
399:     }
400: 
401:     if (this.state === 'patrol') {
402:       const d = this.moveTowards(this.patrolTarget, dt, 2.15, lab, jungle, playerInside);
403:       if (d < 4 || this.stateTimer > 24) this.choosePatrolTarget();
404:       if (this.state === 'patrol' && this.suspicion > 0.6) this.setState('investigate', 'suspicion');
405:     } else if (this.state === 'investigate') {
406:       const target = this.lastHeardAge < 7 ? this.lastHeard : this.patrolTarget;
407:       const d = this.moveTowards(target, dt, 4.25 + this.aggression * 0.5, lab, jungle, playerInside);
408:       if (d < 3.4 || this.stateTimer > 28) {
409:         this.setState('search', 'arrived');
410:         this.searchAngle = this.yaw;
411:       }
412:     } else if (this.state === 'chase') {
413:       this.chaseDuration += dt;
414:       // Blind pursuit: it runs to the freshest acoustic fix, not the player's
415:       // live position. A silent, stationary player can break the lock.
416:       let target = this.lastHeard.clone();
417:       const lead = clamp(this.lastHeardAge * 0.8, 0, 4.6);
418:       if (this.lastHeardAge < 2.1) {
419:         target.x += Math.sin(player.yaw) * lead * 0.4;
420:         target.z += Math.cos(player.yaw) * lead * 0.4;
421:       }
422:       if (playerInside) {
423:         // Circle the bunker, denied entry.
424:         const dLab = Math.hypot(this.position.x, this.position.z);
425:         const angle = Math.atan2(this.position.z, this.position.x) + dt * 0.3;
426:         target.set(Math.cos(angle) * 12.5, 0, Math.sin(angle) * 12.5);
427:         if (dLab < 11.4) this.setState('lurk', 'sanctuary');
428:       }
429:       const d = this.moveTowards(target, dt, 9.17, lab, jungle, playerInside);
430:       if (playerInside && lab.isInside(this.position.x, this.position.z, -1.5)) this.setState('lurk', 'sanctuary');
431:       if (this.lastHeardAge > 8.5 || (d < 2.2 && this.lastHeardAge > 4.5)) {
432:         this.setState('search', 'lost');
433:         this.searchAngle = this.yaw;
434:       }
435:       if (distance < 2.65 && !playerInside) this.startAttack(player);
436:     } else if (this.state === 'search') {
437:       this.searchAngle += dt * 0.85;
438:       const sp = this.position;
439:       const target = _target.set(sp.x + Math.sin(this.searchAngle) * 3.8, 0, sp.z + Math.cos(this.searchAngle) * 3.8);
440:       this.moveTowards(target, dt, 1.55, lab, jungle, playerInside);
441:       if (this.stateTimer > 7.5) {
442:         this.setState('patrol', 'search exhausted');
443:         this.choosePatrolTarget();
444:       }
445:     } else if (this.state === 'lurk') {
446:       this.speed = damp(this.speed, 0, 6, dt);
447:       this.velocity.multiplyScalar(Math.exp(-4 * dt));
448:       const angle = Math.atan2(-this.position.z, -this.position.x);
