548:     if (!this.pointerLocked && !this.mouseDrag) return;
549:     const dx = event.movementX || 0;
550:     const dy = event.movementY || 0;
551:     this.camYaw -= dx * 0.0023;
552:     this.orbitPitch = clamp(this.orbitPitch + dy * 0.0018, 0.02, 1.05);
