361:     joy.addEventListener('pointerup', resetJoy);
362:     joy.addEventListener('pointercancel', resetJoy);
363:     look.addEventListener('pointerdown', (event) => {
364:       lookId = event.pointerId;
365:       lookX = event.clientX;
366:       lookY = event.clientY;
367:       look.setPointerCapture(event.pointerId);
368:     });
369:     look.addEventListener('pointermove', (event) => {
370:       if (lookId !== event.pointerId) return;
371:       const dx = event.clientX - lookX;
