518:   onKeyDown(event) {
519:     const code = event.code;
520:     if (['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ShiftLeft', 'ShiftRight', 'Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'KeyE', 'KeyC', 'KeyV', 'KeyF', 'KeyM', 'Tab'].includes(code)) {
521:       event.preventDefault();
522:     }
523:     if (code === 'KeyM') {
524:       if (this.state === 'playing') this.openMap();
525:       else if (this.state === 'map') this.closeMap();
526:       return;
527:     }
528:     if (code === 'Escape') {
529:       if (this.state === 'map') this.closeMap();
530:       else if (this.state === 'playing') this.pause();
531:       return;
532:     }
533:     if (this.state !== 'playing') return;
534:     if (event.repeat) {
535:       this.keys.add(code);
536:       return;
537:     }
538:     this.keys.add(code);
539:     if (code === 'KeyE') this.tryInteract();
540:     if (code === 'KeyV') this.toggleCamera();
541:     if (code === 'KeyF') this.toggleFlashlight();
542:     if (code === 'KeyC') this.toggleCrouch();
543:     if (code === 'Space') this.jumpQueued = true;
