555:   getInput() {
556:     _forward.set(-Math.sin(this.camYaw), 0, -Math.cos(this.camYaw));
557:     _right.set(Math.cos(this.camYaw), 0, -Math.sin(this.camYaw));
558:     let forwardAmount = 0;
559:     let rightAmount = 0;
560:     if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) forwardAmount += 1;
561:     if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) forwardAmount -= 1;
562:     if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) rightAmount += 1;
563:     if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) rightAmount -= 1;
564:     if (this.touchMove.active) {
565:       forwardAmount += -this.touchMove.y;
566:       rightAmount += this.touchMove.x;
567:     }
568:     _move.set(0, 0, 0).addScaledVector(_forward, forwardAmount).addScaledVector(_right, rightAmount);
569:     if (_move.lengthSq() > 1) _move.normalize();
570:     return {
571:       move: _move,
572:       sprint: this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') || this.touchSprint,
573:       crouch: this.crouchToggle,
574:       jump: this.jumpQueued,
575:     };
576:   }
