699:   /**
700:    * Door panels travel together, so their trim, rails and plating can share a
701:    * handful of merged meshes. The status indicator stays separate because its
702:    * material colour is animated per door.
703:    */
704:   mergeDoorPanels() {
705:     for (const door of this.doors) {
706:       for (const panel of door.panels) {
707:         const group = panel.group;
708:         const byMaterial = new Map();
709:         const remove = [];
710:         for (const child of group.children) {
711:           if (!child.isMesh || child === panel.indicator) continue;
712:           const material = child.material;
713:           if (!material || Array.isArray(material)) continue;
714:           child.updateMatrix();
715:           const key = material.uuid;
716:           if (!byMaterial.has(key)) byMaterial.set(key, { material, geometries: [], cast: false });
717:           const bucket = byMaterial.get(key);
718:           const geo = child.geometry.clone();
719:           geo.applyMatrix4(child.matrix);
720:           bucket.geometries.push(geo);
721:           bucket.cast = bucket.cast || child.castShadow;
722:           remove.push(child);
723:         }
724:         for (const child of remove) {
725:           group.remove(child);
726:           child.geometry.dispose();
727:         }
728:         for (const bucket of byMaterial.values()) {
729:           const merged = mergeGeometries(bucket.geometries, false);
730:           if (!merged) continue;
731:           const mesh = new THREE.Mesh(merged, bucket.material);
732:           mesh.castShadow = bucket.cast;
733:           mesh.receiveShadow = true;
734:           group.add(mesh);
735:           for (const geo of bucket.geometries) geo.dispose();
736:         }
737:       }
738:     }
739:   }
