741:   mergeStaticGeometry() {
742:     this.group.updateMatrixWorld(true);
743:     const byMaterial = new Map();
744:     const remove = [];
745:     const traverse = (object, locked) => {
746:       const keep = locked || object.userData.keepUnmerged;
747:       if (object !== this.group && object.isMesh && !keep) {
748:         const material = object.material;
749:         if (material && !Array.isArray(material)) {
750:           const key = material.uuid;
751:           if (!byMaterial.has(key)) byMaterial.set(key, { material, geometries: [], cast: false, receive: false });
752:           const bucket = byMaterial.get(key);
753:           const geo = object.geometry.clone();
754:           geo.applyMatrix4(object.matrixWorld);
755:           bucket.geometries.push(geo);
756:           bucket.cast = bucket.cast || object.castShadow;
757:           bucket.receive = bucket.receive || object.receiveShadow;
758:           remove.push(object);
759:         }
760:       }
761:       for (const child of object.children) traverse(child, keep);
762:     };
763:     traverse(this.group, false);
764:     for (const object of remove) {
765:       object.parent.remove(object);
766:       object.geometry.dispose();
767:     }
768:     for (const bucket of byMaterial.values()) {
769:       if (!bucket.geometries.length) continue;
770:       const merged = mergeGeometries(bucket.geometries, false);
771:       if (!merged) continue;
772:       const mesh = new THREE.Mesh(merged, bucket.material);
773:       mesh.castShadow = bucket.cast;
774:       mesh.receiveShadow = bucket.receive;
775:       this.group.add(mesh);
776:       for (const geo of bucket.geometries) geo.dispose();
777:     }
778:   }
