832:   update(dt) {
833:     this.elapsed += dt;
834:     const t = this.elapsed;
835:     for (const door of this.doors) {
836:       if (door.busy) {
837:         door.moveTime += dt;
838:         const duration = 2.9;
839:         const raw = clamp(door.moveTime / duration, 0, 1);
840:         const eased = easeInOutCubic(raw);
841:         door.progress = door.target > 0.5 ? eased : 1 - eased;
842:         if (raw >= 1) {
843:           door.progress = door.target;
844:           door.state = door.target > 0.5 ? 'open' : 'closed';
845:           door.busy = false;
846:         }
847:       }
848:       const p = door.progress;
849:       for (const panel of door.panels) {
850:         panel.group.position.x = panel.baseX + panel.side * 1.48 * p;
851:       }
852:       const indicatorColor = p > 0.9 ? 0x76ff9e : p > 0.05 ? 0xffb35c : 0xff5038;
853:       for (const mat of door.indicatorMaterials) mat.color.setHex(indicatorColor);
854:       door.swLight.material.color.setHex(p > 0.9 ? 0x76ff9e : 0xff5038);
855:       door.leverPivot.rotation.x = THREE.MathUtils.damp(door.leverPivot.rotation.x, door.target > 0.5 ? -0.9 : 0, 8, dt);
856:       const sway = Math.sin(t * 2.3 + door.pos.x) * 0.01;
857:       door.swRing.scale.setScalar(1 + sway);
858:       door.collider.active = p < 0.52;
859:     }
860:     if (this.holo) {
861:       this.holo.rotation.y += dt * 0.17;
862:       this.holo.position.y = this.holoBase + Math.sin(t * 1.2) * 0.035;
863:     }
864:     // Emissive strips flicker very subtly.
865:     const flicker = 0.92 + Math.sin(t * 11.3) * 0.015 + Math.sin(t * 3.1) * 0.04;
866:     this.materials.cyanGlow.color.setRGB(0.47 * flicker, 1 * flicker, 0.86 * flicker);
867:   }
