520:     if (['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ShiftLeft', 'ShiftRight', 'Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'KeyE', 'KeyC', 'KeyV', 'KeyF', 'KeyM', 'Tab'].includes(code)) {
521:       event.preventDefault();
522:     }
523:     if (code === 'KeyM') {
524:       if (this.state === 'playing') this.openMap();
525:       else if (this.state === 'map') this.closeMap();
526:       return;
527:     }
528:     if (code === 'Escape') {
