530:       else if (this.state === 'playing') this.pause();
531:       return;
532:     }
533:     if (this.state !== 'playing') return;
534:     if (event.repeat) {
535:       this.keys.add(code);
536:       return;
537:     }
538:     this.keys.add(code);
539:     if (code === 'KeyE') this.tryInteract();
540:     if (code === 'KeyV') this.toggleCamera();
541:     if (code === 'KeyF') this.toggleFlashlight();
