560:     if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) forwardAmount += 1;
561:     if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) forwardAmount -= 1;
562:     if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) rightAmount += 1;
