277:   buildDoor(def) {
278:     const m = this.materials;
279:     const group = new THREE.Group();
280:     group.position.copy(def.pos);
281:     group.rotation.y = def.angle;
282:     this.group.add(group);
283: 
284:     const doorW = 3.15;
285:     const doorH = 3.62;
286:     const left = new THREE.Vector3(-def.outward.z, 0, def.outward.x).multiplyScalar(-1);
287: 
288:     // Heavy frame with bolts.
289:     for (const side of [-1, 1]) {
290:       box(group, { w: 0.42, h: 3.86, d: 0.58, x: side * 1.79, y: 1.93, z: 0, material: m.steelDark });
291:       for (let i = 0; i < 10; i += 1) {
292:         box(group, { w: 0.075, h: 0.075, d: 0.03, x: side * 1.79, y: 0.42 + i * 0.33, z: 0.31, material: m.steel, cast: false });
293:       }
294:     }
295:     box(group, { w: 4.0, h: 0.5, d: 0.58, x: 0, y: 3.86, z: 0, material: m.steelDark });
296:     box(group, { w: 3.47, h: 0.1, d: 0.64, x: 0, y: 3.55, z: 0, material: m.hazard, cast: false });
297:     box(group, { w: 0.38, h: 0.07, d: 0.7, x: 0, y: 4.12, z: 0, material: m.trim });
298: 
299:     // Door slabs.
300:     const panelMat = m.steel;
301:     const panelDark = m.steelDark;
302:     const panels = [];
303:     for (const side of [-1, 1]) {
304:       const panelGroup = new THREE.Group();
305:       panelGroup.position.x = side * 0.75;
306:       panelGroup.userData.keepUnmerged = true;
307:       group.add(panelGroup);
308:       const slab = box(panelGroup, { w: 1.51, h: 3.42, d: 0.26, y: 1.72, material: panelMat });
309:       for (const y of [0.55, 1.7, 2.74]) {
310:         box(panelGroup, { w: 1.4, h: 0.11, d: 0.32, y, material: panelDark });
311:         box(panelGroup, { w: 1.23, h: 0.035, d: 0.33, y: y + 0.1, material: m.hazard, cast: false });
312:       }
313:       // Piston rails.
314:       box(panelGroup, { w: 0.16, h: 2.65, d: 0.35, x: side * 0.52, y: 1.72, material: panelDark });
315:       box(panelGroup, { w: 0.055, h: 2.25, d: 0.38, x: side * 0.52, y: 1.72, material: m.cyanGlow, cast: false });
316:       const lightMat = m.redGlow.clone();
317:       const indicator = box(panelGroup, { w: 0.12, h: 0.12, d: 0.03, x: side * 0.27, y: 3.18, z: 0.16, material: lightMat, cast: false });
318:       panels.push({ group: panelGroup, side, indicator, baseX: side * 0.75 });
319:     }
320:     // Hydraulic roof pistons.
321:     for (const side of [-1, 1]) {
322:       const piston = box(group, { w: 0.15, h: 0.3, d: 0.8, x: side * 0.85, y: 3.72, z: 0.1, material: m.rust });
323:       piston.rotation.x = 0.1;
324:       box(group, { w: 0.1, h: 0.1, d: 0.9, x: side * 0.85, y: 3.7, z: 0.42, material: m.steel, cast: false });
325:     }
326: 
327:     // Tactile control switch, mounted on the LEFT side as viewed from inside.
328:     // Door groups are rotated into place, so the physical left position and
329:     // inward face are resolved into the group's local coordinate system.
330:     const northSouth = def.outward.x === 0;
331:     const switchGroup = new THREE.Group();
332:     switchGroup.position.set(northSouth ? -2.18 : 2.18, 1.35, northSouth ? 0.29 : -0.29);
333:     switchGroup.rotation.y = northSouth ? 0 : Math.PI;
334:     switchGroup.userData.keepUnmerged = true;
335:     group.add(switchGroup);
336: 
337:     box(switchGroup, { w: 0.42, h: 0.66, d: 0.16, material: m.steelDark });
338:     box(switchGroup, { w: 0.34, h: 0.5, d: 0.19, material: m.steel });
339:     const leverPivot = new THREE.Group();
340:     leverPivot.position.set(0, 0.08, 0.14);
341:     switchGroup.add(leverPivot);
342:     box(leverPivot, { w: 0.06, h: 0.28, d: 0.06, y: -0.12, material: m.rust });
343:     box(leverPivot, { w: 0.11, h: 0.085, d: 0.15, y: -0.26, material: m.hazard });
344:     const swLightMat = m.greenGlow.clone();
345:     const swLight = box(switchGroup, { w: 0.075, h: 0.075, d: 0.04, x: 0.13, y: 0.22, z: 0.11, material: swLightMat, cast: false });
346:     const swRing = new THREE.Mesh(new THREE.RingGeometry(0.1, 0.12, 12), new THREE.MeshBasicMaterial({ color: 0x81e16d, side: THREE.DoubleSide, transparent: true, opacity: 0.6 }));
347:     swRing.position.set(0.13, 0.22, 0.12);
348:     switchGroup.add(swRing);
349: 
350:     // Label plate.
351:     const labelTexture = makeTextTexture(`AIRLOCK ${def.label}`, { width: 256, height: 64, size: 22, color: '#b9d391', bg: '#111b13', subtle: true });
352:     plane(switchGroup, { w: 0.5, h: 0.14, y: 0.45, z: 0.085, material: new THREE.MeshBasicMaterial({ map: labelTexture, toneMapped: false }) });
353: 
354:     // Exterior hazard chevrons.
355:     const outsideSign = new THREE.Mesh(new THREE.PlaneGeometry(1.35, 0.27), new THREE.MeshBasicMaterial({
356:       map: makeTextTexture(`M-08 HABITAT // ${def.name}`, { width: 512, height: 80, size: 26, color: '#bcce8c', bg: '#13170e' }),
357:       toneMapped: false,
358:     }));
359:     outsideSign.position.set(0, 3.1, -0.37);
360:     outsideSign.rotation.y = Math.PI;
361:     group.add(outsideSign);
362: 
363:     // Collider blocking the doorway when closed.
364:     const collider = {
365:       minX: def.pos.x - (def.outward.x !== 0 ? 0.4 : 1.6),
366:       maxX: def.pos.x + (def.outward.x !== 0 ? 0.4 : 1.6),
367:       minZ: def.pos.z - (def.outward.z !== 0 ? 0.4 : 1.6),
368:       maxZ: def.pos.z + (def.outward.z !== 0 ? 0.4 : 1.6),
369:       kind: 'door',
370:       active: true,
371:     };
372:     this.colliders.push(collider);
373: 
374:     const door = {
375:       ...def,
376:       group,
377:       panels,
378:       leverPivot,
379:       swLight,
380:       swRing,
381:       collider,
382:       progress: 0,
383:       target: 0,
384:       state: 'closed',
385:       busy: false,
386:       moveTime: 0,
387:       switchPosition: new THREE.Vector3(),
388:       switchGroup,
389:       indicatorMaterials: panels.map((p) => p.indicator.material),
390:     };
391:     switchGroup.getWorldPosition(door.switchPosition);
392:     const worldSwitch = new THREE.Vector3();
393:     switchGroup.getWorldPosition(worldSwitch);
394:     door.switchPosition.copy(worldSwitch);
395:     door.interactable = {
396:       id: `door-${def.id}`,
397:       kind: 'door',
398:       label: `HYDRAULIC DOOR ${def.label}`,
399:       action: () => this.toggleDoor(door),
400:       position: worldSwitch,
401:       range: 2.1,
402:       door,
403:     };
404:     this.interactables.push(door.interactable);
405:     return door;
406:   }
