const fs = require('fs');
(async () => {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const page = targets.find((t) => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0;
  const pending = new Map();
  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    if (pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
    }
  };
  const send = (method, params = {}) => new Promise((resolve) => {
    const commandId = ++id;
    pending.set(commandId, resolve);
    ws.send(JSON.stringify({ id: commandId, method, params }));
  });
  await send('Runtime.enable');
  await send('Page.enable');
  const start = await send('Runtime.evaluate', { expression: "document.querySelector('#start-btn').click(); 'clicked'", returnByValue: true });
  await new Promise((resolve) => setTimeout(resolve, 2200));
  const state = await send('Runtime.evaluate', { expression: "({ startHidden: getComputedStyle(document.querySelector('#start-screen')).display === 'none', hudVisible: getComputedStyle(document.querySelector('#hud')).display !== 'none', title: document.title, canvas: [document.querySelector('canvas').width, document.querySelector('canvas').height], visibleText: document.querySelector('#hud').innerText.slice(0, 350) })", returnByValue: true });
  const shot = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync('/tmp/opencode/ape-project-gameplay.png', Buffer.from(shot.result.data, 'base64'));
  console.log(JSON.stringify({ click: start.result?.result?.value, state: state.result?.result?.value, screenshot: '/tmp/opencode/ape-project-gameplay.png' }, null, 2));
  ws.close();
})();
